html:
{#
  Print Format: Daily Cash Closer
  Type: Custom (tick "Custom Format"), DocType: Daily Cash Closer
  NOTE: no CSS var() anywhere — wkhtmltopdf's WebKit does not support them.
  Colours: navy #17276B · orange #EF7C21
  variance = total_collection - total_payments
#}

{% set n_coll = doc.daily_collection_detail|length %}
{% set n_pay  = doc.daily_payment_mode_detail|length %}
{% set n_rows = [n_coll, n_pay, 3]|max %}

{% set has_var       = doc.meta.get_field("variance") %}
{% set has_balances  = doc.meta.get_field("account_balance_detail") %}
{% set has_bal_total = doc.meta.get_field("total_account_balance") %}

{# Account-balance column totals. Computed with a namespace so blank/None
   cells fall back to 0 instead of raising. #}
{% set bal = namespace(amount=0, erp_amount=0, varriance=0) %}
{% for row in doc.account_balance_detail %}
  {% set bal.amount     = bal.amount     + (row.amount or 0) %}
  {% set bal.erp_amount = bal.erp_amount + (row.erp_amount or 0) %}
  {% set bal.varriance  = bal.varriance  + (row.varriance or 0) %}
{% endfor %}

<style>
  /* Force backgrounds to survive the PDF renderer */
  .dcc, .dcc * {
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
  }

  .dcc { font-family: "Helvetica Neue", Arial, sans-serif; color: #222; font-size: 12px; }

  .dcc-title { text-align: center; margin: 6px 0 14px; }
  .dcc-title h1 {
    margin: 0;
    font-size: 21px;
    font-weight: bold;
    letter-spacing: 0.28em;
    text-transform: uppercase;
    color: #17276B;
  }
  .dcc-title .dcc-underline {
    display: inline-block;
    width: 150px;
    height: 3px;
    background-color: #EF7C21;
    margin-top: 6px;
  }

  .dcc-refline { width: 100%; margin-bottom: 12px; font-size: 12px; }
  .dcc-refline td { padding: 0; }
  .dcc-refline .dcc-r { text-align: right; }
  .dcc-refline b { color: #17276B; }

  .dcc-box {
    border: 1.5px solid #EF7C21;
    border-radius: 4px;
    padding: 10px 12px;
    margin-bottom: 16px;
  }
  .dcc-box table { width: 100%; table-layout: fixed; }
  .dcc-box td { padding: 3px 8px 3px 0; vertical-align: top; }
  .dcc-box .dcc-k { display: block; font-size: 10.5px; font-weight: bold; color: #17276B; }
  .dcc-box .dcc-v { font-size: 12px; color: #222; }

  /* Gutter comes from cell padding, NOT border-spacing — border-spacing also
     insets the outer edges, which made these columns narrower than the
     full-width sections above and below them. */
  .dcc-cols {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
  }
  .dcc-cols > tbody > tr > td { width: 50%; vertical-align: top; padding: 0; }
  .dcc-cols td.dcc-cl { padding-right: 5px; }
  .dcc-cols td.dcc-cr { padding-left: 5px; }
  .dcc-cols > tbody > tr.dcc-totalrow > td { padding-top: 6px; }
  .dcc-cols > tbody > tr.dcc-netrow > td { padding-top: 6px; }

  table.dcc-grid { width: 100%; border-collapse: collapse; table-layout: fixed; }
  table.dcc-grid thead th {
    background-color: #17276B;
    color: #ffffff;
    font-size: 10px;
    font-weight: bold;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    text-align: left;
    padding: 7px 8px;
    border: 1px solid #17276B;
  }
  table.dcc-grid td {
    height: 26px;
    padding: 4px 8px;
    border: 1px solid #E4E4E4;
    font-size: 11.5px;
    line-height: 1.2;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
  }
  table.dcc-grid col.dcc-c-sn { width: 30px; }
  table.dcc-grid col.dcc-c-amt { width: 88px; }
  table.dcc-grid col.dcc-c-amt-wide { width: 130px; }
  /* Numeric columns for the three-figure Account Balances grid.
     Bump this one width to resize all three together. */
  table.dcc-grid col.dcc-c-amt-sm { width: 105px; }
  table.dcc-grid th.dcc-tight, table.dcc-grid td.dcc-tight { padding-left: 5px; padding-right: 7px; }
  table.dcc-grid th.dcc-tight { font-size: 10px; letter-spacing: 0.04em; }
  table.dcc-grid td.dcc-tight { font-size: 11.5px; }
  table.dcc-grid td.dcc-sn { text-align: center; color: #EF7C21; font-weight: bold; }
  table.dcc-grid td.dcc-name { font-weight: bold; color: #17276B; }
  table.dcc-grid th.dcc-num, table.dcc-grid td.dcc-num { text-align: right; }

  /* Totals row sitting inside a grid */
  table.dcc-grid tr.dcc-gridtotal td {
    background-color: #17276B;
    color: #ffffff;
    font-weight: bold;
    border: 1px solid #17276B;
    letter-spacing: 0.03em;
  }
  table.dcc-grid tr.dcc-gridtotal td.dcc-sn { color: #ffffff; }
  table.dcc-grid tr.dcc-gridtotal td.dcc-name { color: #ffffff; }

  .dcc-totalbar {
    width: 100%;
    background-color: #17276B;
    border-collapse: collapse;
    table-layout: fixed;
  }
  .dcc-totalbar td {
    background-color: #17276B;
    color: #ffffff;
    padding: 8px;
    font-weight: bold;
    font-size: 12px;
    letter-spacing: 0.04em;
  }
  .dcc-totalbar td.dcc-num { text-align: right; white-space: nowrap; width: 100px; }

  /* Net variance bar — orange so it reads apart from the two navy totals */
  .dcc-netbar {
    width: 100%;
    background-color: #EF7C21;
    border-collapse: collapse;
    table-layout: fixed;
  }
  .dcc-netbar td {
    background-color: #EF7C21;
    color: #ffffff;
    padding: 8px;
    font-weight: bold;
    font-size: 12.5px;
    letter-spacing: 0.04em;
  }
  .dcc-netbar td.dcc-num { text-align: right; white-space: nowrap; width: 130px; }

  .dcc-sectionhead {
    font-size: 11px;
    font-weight: bold;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #17276B;
    margin: 20px 0 8px;
    padding-bottom: 4px;
    border-bottom: 2px solid #EF7C21;
  }

  .dcc-remarks {
    margin-top: 12px;
    font-size: 11.5px;
    border: 1px solid #E4E4E4;
    border-left: 3px solid #EF7C21;
    padding: 8px 10px;
  }

  .dcc-sign { width: 100%; margin-top: 40px; table-layout: fixed; }
  .dcc-sign td { width: 33.33%; padding-right: 18px; font-size: 10.5px; color: #17276B; font-weight: bold; }
  .dcc-sign .dcc-rule { border-top: 1px solid #999999; padding-top: 5px; }
</style>

<div class="dcc">
{{ letter_head }}


  <table class="dcc-refline">
    <tr>
      <td><b>DCC No.</b> {{ doc.name }}</td>
      <td class="dcc-r"><b>Dated:</b> {{ doc.get_formatted("date") }}</td>
    </tr>
  </table>

  <div class="dcc-box">
    <table>
      <tr>
        <td style="width:30%;">
          <span class="dcc-k">User</span>
          <span class="dcc-v">{{ doc.username or doc.user or doc.owner }}</span>
        </td>
        <td style="width:25%;">
          <span class="dcc-k">Date</span>
          <span class="dcc-v">{{ doc.get_formatted("date") }}</span>
        </td>
        <td style="width:25%;">
          <span class="dcc-k">Collection Lines</span>
          <span class="dcc-v">{{ n_coll }}</span>
        </td>
        <td style="width:20%;">
          <span class="dcc-k">Status</span>
          <span class="dcc-v">
           Submitted
          </span>
        </td>
      </tr>
    </table>
  </div>

  <table class="dcc-cols">
    <tbody>
      <tr>
        <td class="dcc-cl">
          <table class="dcc-grid">
            <colgroup><col class="dcc-c-sn"><col><col class="dcc-c-amt"></colgroup>
            <thead>
              <tr bgcolor="#17276B">
                <th bgcolor="#17276B">SN.</th>
                <th bgcolor="#17276B">Collection</th>
                <th bgcolor="#17276B" class="dcc-num">Amount</th>
              </tr>
            </thead>
            <tbody>
              {% for row in doc.daily_collection_detail %}
              <tr>
                <td class="dcc-sn">{{ loop.index }}</td>
                <td class="dcc-name" title="{{ row.description }}">{{ row.description }}</td>
                <td class="dcc-num">{{ row.get_formatted("amount") }}</td>
              </tr>
              {% endfor %}
              {% for i in range(n_rows - n_coll) %}
              <tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr>
              {% endfor %}
            </tbody>
          </table>
        </td>

        <td class="dcc-cr">
          <table class="dcc-grid">
            <colgroup><col class="dcc-c-sn"><col><col class="dcc-c-amt"></colgroup>
            <thead>
              <tr bgcolor="#17276B">
                <th bgcolor="#17276B">SN.</th>
                <th bgcolor="#17276B">Payment</th>
                <th bgcolor="#17276B" class="dcc-num">Amount</th>
              </tr>
            </thead>
            <tbody>
              {% for row in doc.daily_payment_mode_detail %}
              <tr>
                <td class="dcc-sn">{{ loop.index }}</td>
                <td class="dcc-name" title="{{ row.account }}">{{ (row.account or "").split(" - ")[0] }}</td>
                <td class="dcc-num">{{ row.get_formatted("amount") }}</td>
              </tr>
              {% endfor %}
              {% for i in range(n_rows - n_pay) %}
              <tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr>
              {% endfor %}
            </tbody>
          </table>
        </td>
      </tr>

      <tr class="dcc-totalrow">
        <td class="dcc-cl">
          <table class="dcc-totalbar" bgcolor="#17276B">
            <tr bgcolor="#17276B">
              <td bgcolor="#17276B">Total Collection</td>
              <td bgcolor="#17276B" class="dcc-num">{{ doc.get_formatted("total_collection") }}</td>
            </tr>
          </table>
        </td>
        <td class="dcc-cr">
          <table class="dcc-totalbar" bgcolor="#17276B">
            <tr bgcolor="#17276B">
              <td bgcolor="#17276B">Total Payments</td>
              <td bgcolor="#17276B" class="dcc-num">{{ doc.get_formatted("total_payments") }}</td>
            </tr>
          </table>
        </td>
      </tr>

      {% if has_var %}
      {# Full-width bar spanning both columns. #}
      <tr class="dcc-netrow">
        <td colspan="2">
          <table class="dcc-netbar" bgcolor="#EF7C21">
            <tr bgcolor="#EF7C21">
              <td bgcolor="#EF7C21">Variance (Total Collection - Total Payments)</td>
              <td bgcolor="#EF7C21" class="dcc-num">{{ doc.get_formatted("variance") }}</td>
            </tr>
          </table>
        </td>
      </tr>
      {% endif %}
    </tbody>
  </table>

  {% if has_balances %}
  <div class="dcc-sectionhead">Account Balances</div>
  <table class="dcc-grid">
    {# 5 cols to match the 5 columns; the three numeric ones are narrow. #}
    <colgroup>
      <col class="dcc-c-sn">
      <col>
      <col class="dcc-c-amt-sm">
      <col class="dcc-c-amt-sm">
      <col class="dcc-c-amt-sm">
    </colgroup>
    <thead>
      <tr bgcolor="#17276B">
        <th bgcolor="#17276B">No.</th>
        <th bgcolor="#17276B">Account</th>
        <th bgcolor="#17276B" class="dcc-num dcc-tight">Actual</th>
        <th bgcolor="#17276B" class="dcc-num dcc-tight">ERP</th>
        <th bgcolor="#17276B" class="dcc-num dcc-tight">Varriance</th>
      </tr>
    </thead>
    <tbody>
      {% for row in doc.account_balance_detail %}
      <tr>
        <td class="dcc-sn">{{ loop.index }}</td>
        <td class="dcc-name" title="{{ row.account }}">{{ row.account }}</td>
        <td class="dcc-num dcc-tight">{{ row.get_formatted("amount") }}</td>
        <td class="dcc-num dcc-tight">{{ row.get_formatted("erp_amount") }}</td>
        <td class="dcc-num dcc-tight">{{ row.get_formatted("varriance") }}</td>
      </tr>
      {% endfor %}
      {% if not doc.account_balance_detail %}
      <tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr>
      {% endif %}

      {# Column totals — kept inside the grid so the figures line up under
         their own columns. #}
      <tr class="dcc-gridtotal" bgcolor="#17276B">
        <td bgcolor="#17276B" class="dcc-sn">&nbsp;</td>
        <td bgcolor="#17276B" class="dcc-name">Total</td>
        <td bgcolor="#17276B" class="dcc-num dcc-tight">
          {{ frappe.format_value(bal.amount, {"fieldtype": "Currency"}) }}
        </td>
        <td bgcolor="#17276B" class="dcc-num dcc-tight">
          {{ frappe.format_value(bal.erp_amount, {"fieldtype": "Currency"}) }}
        </td>
        <td bgcolor="#17276B" class="dcc-num dcc-tight">
          {{ frappe.format_value(bal.varriance, {"fieldtype": "Currency"}) }}
        </td>
      </tr>
    </tbody>
  </table>


  {% endif %}

  {% if doc.meta.get_field("remarks") and doc.remarks %}
  <div class="dcc-sectionhead">Remarks</div>
  <div class="dcc-remarks">{{ doc.remarks }}</div>
  {% endif %}

  <table class="dcc-sign">
    <tr>
      <td><div class="dcc-rule">Prepared by</div></td>
      <td><div class="dcc-rule">Verified by</div></td>
      <td><div class="dcc-rule">Approved by</div></td>
    </tr>
  </table>

</div>
